_observed_bowl_rim_arc_fit = observed_bowl_rim

def observed_bowl_rim(robo, color):
    try:
        return _observed_bowl_rim_arc_fit(robo, color)
    except RuntimeError as error:
        if 'Rim arc residual' not in str(error):
            raise
    meta = robo.camera_meta('cam_head')
    seg = robo.segment('the ' + color + ' bowl', camera='cam_head', min_score=0.25)
    if not seg.found or seg.box is None or seg.score < 0.5:
        raise RuntimeError('No reliable bowl extent')
    x0, y0, x1, y1 = seg.box
    if x1 - x0 < 30 or y1 - y0 < 20:
        raise RuntimeError('Bowl extent too small')
    angles = np.linspace(0, 2 * np.pi, 180, endpoint=False)
    circle = np.column_stack((BOWL_RIM_RADIUS_M[color] * np.cos(angles), BOWL_RIM_RADIUS_M[color] * np.sin(angles)))

    def residual(center):
        pts = np.asarray([_world_to_pixel(meta, [*center + off, BOWL_RIM_Z[color]]) for off in circle])
        return np.array([pts[:, 1].min() - x0, pts[:, 1].max() - x1, pts[:, 0].min() - y0])
    initial = _intersect_ray_with_z(meta, *seg.centroid, BOWL_RIM_Z[color])[:2]
    fit = least_squares(residual, initial, bounds=(initial - 0.08, initial + 0.08), max_nfev=100)
    if np.max(abs(residual(fit.x))) > 1.5:
        raise RuntimeError('Bowl top/width inconsistent with circle')
    return {'xy': fit.x.tolist(), 'rim_z_prior': BOWL_RIM_Z[color], 'radius_prior': BOWL_RIM_RADIUS_M[color], 'box_residual_pixels': residual(fit.x).tolist(), 'method': 'sam_top_and_width_fallback'}

def brighter_mouth_candidates(rgb, color):
    a = np.asarray(rgb, dtype=float)
    r, g, b = a.transpose(2, 0, 1)
    if color == 'red':
        mask = (r > 100) & (r < 245) & (g < 20) & (b < 20)
    elif color == 'turquoise':
        mask = (g > 90) & (g < 235) & (b > 90) & (abs(g - b) < 30) & (r < 40)
    elif color == 'violet':
        mask = (r > 70) & (r < 210) & (b - r > 15) & (abs(r - g) < 20)
    else:
        raise ValueError('Unsupported tracked color')
    labels, count = label(mask)
    candidates = []
    for i in range(1, count + 1):
        rc = np.argwhere(labels == i)
        if len(rc) < 200:
            continue
        lo = rc.min(axis=0)
        hi = rc.max(axis=0)
        size = hi - lo + 1
        if not 0.9 < size[0] / size[1] < 3 or len(rc) / float(size[0] * size[1]) < 0.4:
            continue
        candidates.append({'pixel': ((lo + hi) / 2).tolist(), 'area': len(rc), 'bounds': [lo.tolist(), hi.tolist()]})
    return candidates
