import numpy as np

class PourEpisode:

    def __init__(self, policy):
        self.p = policy
        self.phase = 'new'
        self.packet = None
        self.error = None
        self.history = []
        self.last_stereo = None
        self.camera_recovery_allowed = False
        self.observation_revision = 0
        self.observation_invalid = False
        self.acquisition_retry_index = None
        self.capture_state = None

    def _sync_episode_over(self, robo):
        detector = getattr(self.p, '_episode_over_status', None)
        evidence = detector(robo) if callable(detector) else None
        if evidence is None and self.phase != 'episode_over':
            return False
        if self.phase != 'episode_over':
            self.episode_over = evidence
            self._invalidate_observation()
            self.history.append({'operation': 'episode_over', 'evidence': evidence})
        self.phase = 'episode_over'
        self.camera_recovery_allowed = False
        self.acquisition_retry_index = None
        self.error = 'Episode ended; inspect the episode outcome'
        return True

    def status(self, robo):
        self._sync_episode_over(robo)
        return {'phase': self.phase, 'error': self.error, 'pair_index': self.p._bridge_index, 'has_pending_mouth': self.p._bridge_pending is not None, 'camera_recovery_allowed': self.camera_recovery_allowed, 'acquisition_retry_allowed': self.acquisition_retry_index == self.p._bridge_index, 'recovery_context': self.recovery_context(), 'action_count': robo.action_count(), 'episode_outcome_authoritative': True}

    def recovery_context(self):
        """Policy state only; no motion, verdict, or phase reset."""
        if self.phase == 'episode_over':
            return {'episode_over': self.episode_over, 'automatic_replay_allowed': False, 'ordinary_continuation_allowed': False, 'next_step': 'Read the episode outcome; no further controls.'}
        pending = self.p._bridge_pending
        pairs = getattr(self.p, '_bridge_pairs', None)
        index = self.p._bridge_index
        return {'failed_operation': self.history[-1]['operation'] if self.error and self.history else None, 'active_pair': list(pairs[index]) if pairs is not None and index < len(pairs) else None, 'completed_pair_count': index, 'working_arm': pending.get('working') if pending is not None else None, 'color': pending.get('color') if pending is not None else None, 'observation_revision': self.observation_revision, 'saved_images_valid_for_new_answer': self.packet is not None and (not self.observation_invalid), 'next_observations': ['cam_head', 'cam_left_wrist', 'cam_right_wrist'], 'automatic_replay_allowed': False, 'next_step': 'Inspect fresh RGB and proprioception; select a different bounded exterior observer path and call observe. Do not reuse stale images or repeat the stalled pose.' if self.camera_recovery_allowed else 'Inspect fresh RGB/proprioception and the active failed subskill; use public raw tools for an explicit phase-aware recovery. Do not call advance to replay acquisition, reset context, or claim a completed transfer from a failed generator.', 'manual_phase_commit_supported': False, 'return_recovery_available': self._return_recovery_available()}

    def _capture_state(self, robo):
        state = robo.state()
        used = robo.action_count()
        if used is None:
            raise RuntimeError('Action counter unavailable; cannot bind mouth observations')
        arms = {}
        for name in ('left', 'right'):
            arm = state.arm(name)
            values = np.asarray([*arm.joints, *arm.tcp_pos, *arm.eef_quat, arm.gripper], dtype=float)
            if not np.isfinite(values).all():
                raise RuntimeError('Nonfinite robot state')
            arms[name] = values.tolist()
        cameras = {}
        for name in ('cam_left_wrist', 'cam_right_wrist'):
            meta = robo.camera_meta(name)
            cameras[name] = {key: np.asarray(meta[key], dtype=float).tolist() for key in ('intrinsic_matrix', 'extrinsic_matrix')}
        return {'used': int(used), 'step': int(state.step), 'arms': arms, 'cameras': cameras}

    def _bind_observation(self, robo):
        self.capture_state = self._capture_state(robo)

    def _require_current_observation(self, robo):
        current = self._capture_state(robo)
        if self.capture_state is None or current != self.capture_state:
            self.phase = 'blocked'
            self.error = 'Mouth images invalidated by intervening state/control; reobserve'
            self._invalidate_observation()
            self.camera_recovery_allowed = self.p._bridge_pending is not None
            self.history.append({'operation': 'stale_observation', 'phase': self.phase, 'error': self.error})
            raise RuntimeError(self.error)

    def _camera_failure(self, error):
        camera_error = getattr(self.p, 'CameraAcquisitionError', None)
        if isinstance(camera_error, type) and isinstance(error, camera_error):
            return True
        error = str(error)
        return error.startswith(('Observer path rejected ', 'Observer move failed ', 'Exact OPEN paired camera failed ')) or error in ('Observer conservative own-robot envelope failed', 'Independent mouth observations disagree; retain grip')

    def _invalidate_observation(self):
        self.observation_revision += 1
        self.observation_invalid = True
        self.packet = None
        self.capture_state = None
        self.last_stereo = None

    def advance(self, robo):
        if self._sync_episode_over(robo):
            return self.status(robo)
        if self.phase not in ('new', 'pair_completed'):
            raise RuntimeError('Do not replay acquisition; inspect existing phase')
        start_action_count = robo.action_count()
        start_used = start_action_count
        self.acquisition_retry_index = None
        try:
            self.packet = self.p.advance(robo, force_query=True)
            self.observation_revision += 1
            self.observation_invalid = False
            self.phase = 'mouth' if self.packet['catalog']['status'] == 'needs_mouth_pixels' else 'completed'
            self.error = None
            self.camera_recovery_allowed = self.phase == 'mouth'
            if self.phase == 'mouth':
                self._bind_observation(robo)
        except Exception as exc:
            self.phase = 'blocked'
            self.error = str(exc)
            end_action_count = robo.action_count()
            end_used = end_action_count
            if start_used is not None and end_used == start_used and (self.p._bridge_pending is None):
                self.acquisition_retry_index = self.p._bridge_index
            progress = getattr(self.p, '_bridge_camera_progress', None)
            grasp = getattr(self.p, '_bridge_grasp', None)
            camera_error = self._camera_failure(exc)
            if camera_error and isinstance(progress, dict) and isinstance(grasp, dict) and (progress.get('pair_index') == self.p._bridge_index) and (progress.get('color') == grasp.get('color')) and (progress.get('working') == grasp.get('arm')):
                self.p._bridge_pending = dict(progress, grasp=grasp)
                self.camera_recovery_allowed = True
                self.acquisition_retry_index = None
                self._invalidate_observation()
        self.history.append({'operation': 'advance', 'phase': self.phase, 'error': self.error})
        return self.status(robo)

    def images(self):
        if self.packet is None:
            return []
        return self.packet['images']

    def catalog(self):
        return None if self.packet is None else {**self.packet['catalog'], 'observation_revision': self.observation_revision}

    def triangulate(self, robo, answer):
        context = self.p._bridge_pending
        if answer.get('observation_revision') != self.observation_revision:
            raise RuntimeError('Stale camera observation revision; inspect current images')
        if self.observation_invalid:
            raise RuntimeError('Camera sequence failed; obtain a fresh synchronized image pair before answering')
        if context is None or answer.get('request_id') != self.p._bridge_index:
            raise RuntimeError('No matching pending mouth')
        self._require_current_observation(robo)
        views = sorted(answer.get('views', []), key=lambda x: x['view'])
        if len(views) != 2 or [v['view'] for v in views] != [0, 1]:
            raise ValueError('Two distinct views required')
        pixels = []
        for view, meta in zip(views, context['query_views']):
            pixel = np.asarray(view.get('pixel_rc'), dtype=float)
            if view.get('confidence') != 'high' or pixel.shape != (2,) or (not np.isfinite(pixel).all()):
                raise ValueError('Uncertain or invalid mouth pixel')
            if not 0 <= pixel[0] < meta['crop_height'] or not 0 <= pixel[1] < meta['crop_width']:
                raise ValueError('Pixel outside source image')
            pixels.append(pixel + np.array([meta['crop_box_xyxy'][1], meta['crop_box_xyxy'][0]]))
        fit = self.p.triangulate(context['captured'][0][1], pixels[0], context['captured'][1][1], pixels[1])
        self.last_stereo = np.asarray(fit['xyz']).copy()
        return {**fit, 'xyz': self.last_stereo.tolist(), 'no_motion': True}

    def observe(self, robo, offsets):
        if self._sync_episode_over(robo):
            return self.status(robo)
        if not self.camera_recovery_allowed or self.phase not in ('mouth', 'blocked') or self.p._bridge_pending is None:
            raise RuntimeError('Explicit held-mouth context required')
        offsets = np.asarray(offsets, dtype=float)
        if offsets.shape != (2, 3) or not np.isfinite(offsets).all():
            raise ValueError('Two finite camera offsets required')
        if np.any(np.linalg.norm(offsets, axis=1) > 0.5) or np.any(offsets[:, 2] < 0.15):
            raise ValueError('Camera offsets exceed bounded observation region')
        if self.capture_state is not None and self._capture_state(robo) != self.capture_state:
            self._invalidate_observation()
        context = self.p._bridge_pending
        target = None if self.observation_invalid else self.last_stereo if self.last_stereo is not None else context['target']
        try:
            fresh = self.p._prepare_color_mouth(robo, context['color'], context['working'], target_override=target, offsets_override=offsets.tolist())
        except Exception as exc:
            self.error = str(exc)
            self._invalidate_observation()
            self.history.append({'operation': 'observe', 'error': self.error, 'offsets': offsets.tolist()})
            return self.status(robo)
        fresh['grasp'] = context['grasp']
        if self.last_stereo is not None:
            fresh['verification_reference'] = self.last_stereo.tolist()
        self.p._bridge_pending = fresh
        self.packet = self.p._mouth_packet(fresh)
        self.observation_revision += 1
        self.observation_invalid = False
        self.phase = 'mouth'
        self._bind_observation(robo)
        self.error = None
        self.history.append({'operation': 'observe', 'error': None, 'offsets': offsets.tolist()})
        return self.status(robo)

    def apply(self, robo, answer):
        if self._sync_episode_over(robo):
            return self.status(robo)
        if self.phase != 'mouth':
            raise RuntimeError('Cannot replay failed manipulation automatically')
        self.triangulate(robo, answer)
        self.camera_recovery_allowed = False
        try:
            result = self.p.apply_pixels(robo, answer)
            if result.get('needs_independent_mouth_verification'):
                self.packet = self.p.advance(robo, force_query=True)
                self.observation_revision += 1
                self.phase = 'mouth'
                self.camera_recovery_allowed = True
                self.observation_invalid = False
                self._bind_observation(robo)
            elif result.get('pair_completed'):
                self.phase = 'pair_completed'
                self.packet = None
                self.last_stereo = None
            else:
                raise RuntimeError('Unrecognized transfer result')
            self.error = None
        except Exception as exc:
            self.phase = 'blocked'
            self.error = str(exc)
            self._invalidate_observation()
            self.camera_recovery_allowed = self._camera_failure(exc) and self.p._bridge_pending is not None
        self.history.append({'operation': 'apply', 'phase': self.phase, 'error': self.error})
        return self.status(robo)

    def recover_clearance(self, robo, offsets, *, visual_evidence):
        """Explicit retry only before any transfer motion, with new mouth observations."""
        if self._sync_episode_over(robo):
            return self.status(robo)
        entry = getattr(self.p, '_transfer_entry', None)
        pending = self.p._bridge_pending
        if self.phase != 'blocked' or not isinstance(entry, dict) or entry.get('stage') != 'clearance' or (not isinstance(pending, dict)) or (entry.get('pair') != self.p._bridge_index) or (entry.get('task') != str(robo.task)) or (entry.get('color') != pending.get('color')) or (entry.get('working') != pending.get('working')):
            raise RuntimeError('No recoverable pre-transfer clearance boundary; do not replay manipulation')
        if not isinstance(visual_evidence, str) or len(visual_evidence.strip()) < 30:
            raise ValueError('Current visual assessment of retained bottle and observer required')
        working = entry['working']
        current = self.p._held_capture(robo, working)
        self.p._require_held_capture(entry['held'], current)
        if robo.state().truncated:
            raise RuntimeError('Episode limit prevents recovery')
        self.p.replan_observer_clearance(robo, working, visual_evidence=visual_evidence)
        self._invalidate_observation()
        self.camera_recovery_allowed = True
        self.history.append({'operation': 'recover_clearance', 'pair': self.p._bridge_index, 'visual_evidence': visual_evidence})
        return self.observe(robo, offsets)

    def _return_recovery_available(self):
        progress = getattr(self.p, '_bridge_return_progress', None)
        return isinstance(progress, dict) and progress.get('pair_index') == self.p._bridge_index and callable(getattr(self.p, 'resume_return_pair', None))

    def resume_return(self, robo):
        """Explicit recorded return continuation; never reacquire or pour again."""
        if self._sync_episode_over(robo):
            return self.status(robo)
        if self.phase != 'blocked' or not self._return_recovery_available():
            raise RuntimeError('No resumable current return phase; inspect evidence')
        before = self.p._bridge_index
        try:
            result = self.p.resume_return_pair(robo)
            if not result.get('pair_completed') or self.p._bridge_index != before + 1:
                raise RuntimeError('Return completion contract inconsistent')
            self.phase = 'pair_completed'
            self.error = None
            self.packet = None
            self.last_stereo = None
            self.camera_recovery_allowed = False
        except Exception as exc:
            self.phase = 'blocked'
            self.error = str(exc)
        self.history.append({'operation': 'resume_return', 'phase': self.phase, 'error': self.error})
        return self.status(robo)

    def retry_acquisition(self, robo):
        """Explicit fresh-view retry only after a zero-control acquisition failure."""
        if self._sync_episode_over(robo):
            return self.status(robo)
        if self.phase != 'blocked' or self.acquisition_retry_index != self.p._bridge_index or self.p._bridge_pending is not None:
            raise RuntimeError('Acquisition retry requires recorded zero-control failure at current pair')
        state = robo.state()
        if any((float(state.arm(arm).gripper) < 0.9 for arm in ('left', 'right'))):
            raise RuntimeError('Acquisition retry requires both observed grippers open; preserve held objects')
        self.phase = 'pair_completed'
        return self.advance(robo)

def run(robo):
    raise RuntimeError('Use PourEpisode (pour_adaptive): one pair at a time')

class CameraAcquisitionError(RuntimeError):
    """Held-bottle camera acquisition failed; explicit reobservation is safe to request."""
    pass
_bowl_clearance_pose = {}
_bowl_clearance_attempts = {}

def _clearance_snapshot(robo, working):
    state = robo.state()
    observer = 'right' if working == 'left' else 'left'
    poses = {}
    for arm in [working, observer]:
        s = state.arm(arm)
        p = np.asarray(s.tcp_pos, float)
        q = np.asarray(s.eef_quat, float)
        angles = np.asarray([s.pitch, s.yaw, s.roll], float)
        g = float(s.gripper)
        if p.shape != (3,) or q.shape != (4,) or (not np.isfinite(np.r_[p, q, angles, g]).all()) or (not 0.5 < np.linalg.norm(q) < 1.5):
            raise RuntimeError('Invalid pose during clearance; retain bottle and inspect')
        poses[arm] = {'xyz': p.tolist(), 'quat': (q / np.linalg.norm(q)).tolist(), 'angles': angles.tolist(), 'gripper': g}
    return {'poses': poses, 'episode_actions': int(robo.action_count()), 'task': str(robo.task), 'pair': int(_bridge_index), 'working': working, 'observer': observer}

def _clearance_angle(a, b):
    return float(np.degrees(2 * np.arccos(np.clip(abs(np.dot(a, b)), 0.0, 1.0))))

def _clearance_same(a, b):
    if any((a[k] != b[k] for k in ['episode_actions', 'task', 'pair', 'working', 'observer'])):
        return False
    for arm in a['poses']:
        x, y = (a['poses'][arm], b['poses'][arm])
        if np.linalg.norm(np.asarray(x['xyz']) - y['xyz']) > 0.001 or _clearance_angle(x['quat'], y['quat']) > 0.5 or abs(x['gripper'] - y['gripper']) > 0.01:
            return False
    return True

def replan_observer_clearance(robo, working, *, visual_evidence):
    if not isinstance(visual_evidence, str) or len(visual_evidence.strip()) < 30:
        raise ValueError('Explicit current view/held-state assessment required')
    current = _clearance_snapshot(robo, working)
    key = (current['task'], current['pair'], working)
    previous = _bowl_clearance_attempts.pop(key, None)
    print({'explicit_clearance_replan': True, 'previous_attempt': previous, 'current_state': current, 'visual_evidence': visual_evidence, 'scope': 'Explicit agent decision; no motion dispatched and no prior cell replayed'})
    return current

def clear_observer_for_bowl(robo, working):
    before = _clearance_snapshot(robo, working)
    observer = before['observer']
    key = (before['task'], before['pair'], working)
    free = before['poses'][observer]
    held = before['poses'][working]
    if not 0.1 < held['gripper'] < 0.8 or free['gripper'] < 0.9:
        raise RuntimeError('Clearance needs retained bottle and open observer; inspect')
    previous = _bowl_clearance_attempts.get(key)
    if previous is not None:
        if previous['status'] == 'completed' and _clearance_same(before, previous['after']):
            return {'already_at_clearance': True, 'observer': observer}
        raise RuntimeError('Prior clearance attempt or changed context; inspect current views and explicitly replan_observer_clearance, never blindly replay')
    target = np.asarray(free['xyz']) + [0.15 if observer == 'right' else -0.15, 0.0, 0.0]
    attempt = {'status': 'planning', 'before': before, 'target': target.tolist()}
    _bowl_clearance_attempts[key] = attempt
    pitch, yaw, roll = free['angles']
    try:
        previews = []
        selected = None
        for outward_m, down_m in [(0.15, 0.0), (0.1, 0.0), (0.05, 0.0), (0.05, 0.04)]:
            proposal = np.asarray(free['xyz']) + [outward_m if observer == 'right' else -outward_m, 0.0, -down_m]
            preview = robo.preview_move(proposal.tolist(), arm=observer, pitch=pitch, yaw=yaw, roll=roll, path='line')
            previews.append({'outward_m': outward_m, 'down_m': down_m, 'target': proposal.tolist(), 'preview': preview})
            if preview.get('reachable') and (not preview.get('note')) and (not preview.get('ik_error')):
                selected = proposal
                break
        attempt['previews'] = previews
        if selected is None:
            raise RuntimeError('All bounded outward routes unavailable; explicit replan required')
        target = selected
        attempt['target'] = target.tolist()
        print({'bounded_outward_previews': previews, 'selected_target': target.tolist(), 'scope': 'Kinematic preview only; no held-object/scene collision certificate'})
        attempt['status'] = 'motion_dispatched'
        rec = _checked_motion(robo, 'move_to', target.tolist(), arm=observer, pitch=pitch, yaw=yaw, roll=roll, path='line', gripper=robo.OPEN)
        attempt['reply'] = str(rec)
        if not rec.reached or rec.blocked or rec.ik_error or rec.truncated:
            raise RuntimeError('Observer clearance incomplete; retain attempt and reobserve')
        after = _clearance_snapshot(robo, working)
        attempt['after'] = after
        for arm in [working, observer]:
            a, b = (before['poses'][arm], after['poses'][arm])
            if _clearance_angle(a['quat'], b['quat']) > 1.0:
                raise RuntimeError('Orientation changed during clearance; held-mouth transform unsupported')
        h = after['poses'][working]
        _require_held_capture(held, h)
        if np.linalg.norm(np.asarray(h['xyz']) - held['xyz']) > 0.003 or not 0.1 < h['gripper'] < 0.8 or after['poses'][observer]['gripper'] < 0.9:
            raise RuntimeError('Grip/held position changed during clearance')
        if np.linalg.norm(np.asarray(after['poses'][observer]['xyz']) - target) > 0.003:
            raise RuntimeError('Observer achieved pose disagrees with target')
        attempt['status'] = 'completed'
        print({'observer_outward_reply': str(rec), 'no_intermediate_home': True, 'clearance_context': after})
        return {'observer': observer, 'reply': str(rec)}
    except Exception:
        attempt['status'] = 'requires_explicit_replan'
        raise

def red_transfer_from_held(*args, **kwargs):
    raise RuntimeError('This transfer entry is disabled: use PourEpisode with fresh bound observations')

def color_transfer_from_held(*args, **kwargs):
    raise RuntimeError('This transfer entry is disabled: use PourEpisode with fresh bound observations')
_transfer_entry = None

def _held_capture(robo, working):
    a = robo.state().arm(working)
    p = np.asarray(a.tcp_pos, float)
    q = np.asarray(a.eef_quat, float)
    g = float(a.gripper)
    if p.shape != (3,) or q.shape != (4,) or (not np.isfinite(np.r_[p, q, g]).all()) or (not 0.5 < np.linalg.norm(q) < 1.5) or (not 0.1 < g < 0.8):
        raise RuntimeError('Held camera pose/grip unsupported; inspect before recovery')
    return {'xyz': p.tolist(), 'quat': (q / np.linalg.norm(q)).tolist(), 'gripper': g}

def _require_held_capture(reference, current):
    if np.linalg.norm(np.asarray(reference['xyz']) - current['xyz']) > 0.003 or _clearance_angle(reference['quat'], current['quat']) > 1.0 or abs(reference['gripper'] - current['gripper']) > 0.03:
        raise RuntimeError('Held pose changed across camera sequence; invalidate observations and inspect')
_gripper_step_progress = None

def _checked_gripper_step(robo, arm, command, operation, completed=0):
    global _gripper_step_progress
    before = robo.state()
    action_count = robo.action_count()
    _gripper_step_progress = {'operation': operation, 'arm': arm, 'completed_before': completed, 'status': 'before_dispatch', 'action_count_before': action_count}
    if before.truncated:
        _gripper_step_progress['status'] = 'episode_over'
        raise RuntimeError('Episode termination before ' + operation + ' ' + str(_gripper_step_progress))
    initial = float(before.arm(arm).gripper)
    _gripper_step_progress['status'] = 'dispatched'
    try:
        reply = robo.set_gripper(arm, command)
        _gripper_step_progress['reply'] = str(reply)
        current = robo.state()
        after = robo.action_count()
        opening = float(current.arm(arm).gripper)
        _gripper_step_progress.update(action_count_after=after, observed_opening=opening)
        if reply.truncated or current.truncated:
            _gripper_step_progress['status'] = 'episode_over'
            raise RuntimeError('Episode termination during ' + operation)
        if not np.isfinite([reply.opening, opening]).all():
            raise RuntimeError('Nonfinite gripper feedback')
        if command == robo.OPEN:
            if reply.commanded != 'open' or reply.opening < 0.9 or opening < 0.9:
                raise RuntimeError('Opening not achieved')
        elif operation == 'observer_close':
            if reply.commanded != 'closed' or reply.holding or (not 0.0 <= reply.opening <= 0.02) or (not 0.0 <= opening <= 0.02):
                raise RuntimeError('Empty observer closure not established')
        else:
            if reply.commanded != 'closed' or not reply.holding or reply.width_m is None or (not 0.04 < reply.width_m < 0.1) or (not 0.1 < opening < 0.8):
                raise RuntimeError('Supported bottle holding not observed')
            if operation in ('pour_dwell', 'bowl_recovery_close') and abs(opening - initial) > 0.03:
                raise RuntimeError('Material grip change during dwell')
        _gripper_step_progress['status'] = 'completed'
        return reply
    except Exception as exc:
        if _gripper_step_progress['status'] != 'episode_over':
            _gripper_step_progress['status'] = 'requires_live_inspection'
        _gripper_step_progress['error'] = str(exc)
        print({'gripper_step_failure': _gripper_step_progress})
        raise RuntimeError('Gripper operation stopped; do not replay: ' + str(_gripper_step_progress)) from exc

def _require_open_state(robo, arm):
    state = robo.state()
    action_count = robo.action_count()
    opening = float(state.arm(arm).gripper)
    if state.truncated:
        raise RuntimeError('Episode termination; no return withdrawal/home')
    if not np.isfinite(opening) or not 0.9 <= opening <= 1.01:
        raise RuntimeError('Finite observed OPEN state required before withdrawal/home')
    return {'opening': opening, 'action_count': action_count}

def confirm_observed_return_release(robo, *, visual_evidence):
    state = _bridge_return_progress
    if not isinstance(state, dict) or state['pair_index'] != _bridge_index or state['next'] != len(state['path']) or state['released'] or (not isinstance(state.get('release_attempt'), dict)):
        raise RuntimeError('No matching ambiguous release to confirm')
    if state['release_attempt']['status'] != 'requires_live_inspection':
        raise RuntimeError('Release confirmation not available')
    if not isinstance(visual_evidence, str) or len(visual_evidence.strip()) < 20:
        raise RuntimeError('Fresh evidence of supported bottle and empty hand required')
    observed = _require_open_state(robo, state['arm'])
    state['release_attempt']['observed_confirmation'] = {'visual_evidence': visual_evidence, 'observed': observed}
    state['release_attempt']['status'] = 'observed_confirmed'
    state['released'] = True
    return {'confirmed_release': True, 'scope': 'Agent inspection plus observed OPEN; not task success or proof object stability'}
_episode_over_evidence = None

class EpisodeTerminated(RuntimeError):
    pass

def _episode_over_status(robo, reply=None, operation=None):
    global _episode_over_evidence
    if _episode_over_evidence is not None:
        return _episode_over_evidence
    state = robo.state()
    action_count = robo.action_count()
    terminal = bool(getattr(state, 'truncated', False)) or bool(reply.get('truncated', False) if isinstance(reply, dict) else getattr(reply, 'truncated', False))
    grip = globals().get('_gripper_step_progress')
    if isinstance(grip, dict) and grip.get('status') == 'episode_over':
        terminal = True
    if terminal:
        _episode_over_evidence = {'operation': operation, 'state_truncated': bool(getattr(state, 'truncated', False)), 'reply_truncated': bool(reply.get('truncated', False) if isinstance(reply, dict) else getattr(reply, 'truncated', False)), 'reply': str(reply) if reply is not None else None, 'action_count': action_count, 'episode_outcome_authoritative': True, 'ordinary_continuation_allowed': False}
    return _episode_over_evidence

def _checked_motion(robo, method, *args, **kwargs):
    if method not in ('move_to', 'move_both', 'home'):
        raise ValueError('Unsupported motion gate method')
    ended = _episode_over_status(robo, operation='before ' + method)
    if ended is not None:
        raise EpisodeTerminated('Episode ended: ' + str(ended))
    reply = getattr(robo, method)(*args, **kwargs)
    ended = _episode_over_status(robo, reply, method)
    if ended is not None:
        raise EpisodeTerminated('Episode ended: ' + str(ended))
    return reply
